<script setup>
import {ref,onMounted,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import {appointmentService} from '../../services/appointments';import {useClinicContextStore} from '../../stores/clinicContext';import {useAppointmentStore} from '../../stores/appointments';import {terminalStatuses,formatDate} from '../../utils/appointmentDates';import AppointmentStatusBadge from './AppointmentStatusBadge.vue';import FormErrors from '../ui/FormErrors.vue';
const props=defineProps({id:Number});const emit=defineEmits(['changed']);const route=useRoute(),router=useRouter(),context=useClinicContextStore(),store=useAppointmentStore();const a=ref(null),activity=ref(null),error=ref(null),busy=ref(false),confirm=ref(null),reason=ref(''),closeButton=ref(null);
const labels={'confirm':'Confirm Appointment','check-in':'Check In','start-consultation':'Start Consultation','complete':'Complete Appointment','cancel':'Cancel Appointment','no-show':'Mark No Show'};
async function load(){busy.value=true;error.value=null;try{a.value=(await appointmentService.get(props.id)).data.data;activity.value=(await appointmentService.activity(props.id)).data.data;}catch(e){error.value=e;}finally{busy.value=false;}}
function close(){router.push({path:'/app/appointments',query:route.query});}
async function transition(){busy.value=true;error.value=null;try{await appointmentService.action(props.id,confirm.value,{reason:reason.value});confirm.value=null;reason.value='';await load();store.notice='Appointment updated successfully.';emit('changed');}catch(e){error.value=e;}finally{busy.value=false;}}
function trap(event){const elements=[...event.currentTarget.querySelectorAll('button:not(:disabled),a,input,select,textarea')].filter(el=>el.getClientRects().length);const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
onMounted(async()=>{await nextTick();closeButton.value?.focus();load();});
</script>
<template><Teleport to="body"><div class="appointment-drawer-backdrop" @click.self="close" @keydown.esc.stop="confirm?confirm=null:close()"><section class="appointment-drawer" role="dialog" aria-modal="true" aria-labelledby="appointment-detail-title" @keydown.tab="trap"><header><div><small>APPOINTMENT DETAILS</small><h2 id="appointment-detail-title">{{a?.appointment_number || 'Appointment'}}</h2></div><button ref="closeButton" class="btn-secondary" aria-label="Close appointment" @click="close">×</button></header><FormErrors :error="error"/><p v-if="busy" class="empty-state" role="status">Loading…</p><button v-else-if="error&&!a" class="btn" @click="load">Try again</button><template v-if="a"><div class="appointment-detail-patient"><span>{{a.patient.full_name.split(' ').map(p=>p[0]).slice(0,2).join('')}}</span><div><h3>{{a.patient.full_name}}</h3><p>{{a.patient.patient_number}}</p></div><AppointmentStatusBadge :status="a.status"/></div><dl class="appointment-detail-grid"><div><dt>Doctor</dt><dd>{{a.doctor.full_name}}</dd></div><div><dt>Branch</dt><dd>{{a.branch}}</dd></div><div><dt>Date</dt><dd>{{formatDate(a.starts_at.slice(0,10))}}</dd></div><div><dt>Time</dt><dd>{{a.starts_at.slice(11,16)}} – {{a.ends_at.slice(11,16)}}<small>{{context.data.clinic.timezone}}</small></dd></div><div><dt>Visit type</dt><dd>{{a.type || 'Not specified'}}</dd></div><div><dt>Source</dt><dd class="capitalize">{{a.source.replaceAll('_',' ')}}</dd></div><div class="col-span-full"><dt>Reason</dt><dd>{{a.reason || 'Not recorded'}}</dd></div><div class="col-span-full"><dt>Notes</dt><dd class="whitespace-pre-wrap">{{a.notes || 'Not recorded'}}</dd></div><div v-if="a.cancellation_reason" class="col-span-full"><dt>Cancellation reason</dt><dd>{{a.cancellation_reason}}</dd></div><div><dt>Created by</dt><dd>{{a.created_by}}</dd></div><div><dt>Created</dt><dd>{{new Date(a.created_at).toLocaleString('en-GB',{timeZone:context.data.clinic.timezone})}}</dd></div><div v-if="a.completed_at" class="col-span-full"><dt>Completed at</dt><dd>{{a.completed_at}} UTC</dd></div></dl><div class="appointment-detail-actions"><RouterLink v-if="context.allowed('patients')" class="btn-secondary" :to="`/app/patients/${a.patient_id}`">View Patient</RouterLink><RouterLink v-if="context.can('appointments.update')&&!terminalStatuses.includes(a.status)&&a.status!=='in_consultation'" class="btn-secondary" :to="`/app/appointments/${a.id}/edit`">Edit Appointment</RouterLink><RouterLink v-if="context.can('appointments.reschedule')&&!terminalStatuses.includes(a.status)&&a.status!=='in_consultation'" class="btn-secondary" :to="`/app/appointments/${a.id}/reschedule`">Reschedule</RouterLink><template v-for="(definition,action) in store.options?.actions" :key="action"><button v-if="definition.from.includes(a.status)&&context.can(definition.permission)" class="btn" :disabled="busy" @click="confirm=action;error=null">{{labels[action]}}</button></template></div><form v-if="confirm" class="appointment-confirm" @submit.prevent="transition"><h3>{{labels[confirm]}}?</h3><label v-if="confirm==='cancel'" class="field">Cancellation reason *<textarea v-model="reason" required maxlength="2000" rows="3"></textarea></label><p v-else>This will update the appointment's status.</p><div class="flex flex-wrap gap-3 mt-4"><button class="btn-secondary" type="button" :disabled="busy" @click="confirm=null">Keep Appointment</button><button class="btn" :disabled="busy">Confirm {{labels[confirm]}}</button></div></form><details class="appointment-activity"><summary>Activity history</summary><p v-for="item in activity?.data" :key="item.id"><strong>{{item.action.replace('appointment.','').replaceAll('_',' ')}}</strong> · {{item.actor_name}}<small>{{item.created_at}} UTC</small></p><p v-if="activity?.last_page>1" class="hint">Showing the latest 25 events.</p></details></template></section></div></Teleport></template>
